using System;
using System.Collections.Generic;
using System.Linq;
using CashflowChains.Economy;
using CashflowChains.Domain;

namespace CashflowChains.Empire {
 public sealed partial class EmpireAccount {
  public List<DispatchOperation> Dispatches=new List<DispatchOperation>();public List<string> Research=new List<string>();public List<ResearchProject> ResearchQueue=new List<ResearchProject>();
  void ValidateOperations(BalanceConfig config){
   if(Dispatches==null||Research==null||ResearchQueue==null||Dispatches.Any(x=>x==null)||ResearchQueue.Any(x=>x==null)||Dispatches.Select(x=>x.Id).Distinct().Count()!=Dispatches.Count||Research.Distinct().Count()!=Research.Count||ResearchQueue.Count>1||Dispatches.Count(x=>!x.Claimed)>EmpireBenefits.DispatchSlots(config,this))throw new ArgumentException("Invalid operations state");
   foreach(var d in Dispatches){var def=config.Operations.Dispatch(d.Template);if(d.StartedAt<0||d.StartedAt>Economy.LastTrustedAt||d.ReductionBp<0||d.ReductionBp>5000||d.YieldBp<0||d.YieldBp>10000||d.FinishAt-d.StartedAt!=EconomyMath.Duration(def.Seconds,d.ReductionBp)-d.SpeedupSeconds||d.SpeedupSeconds<0||d.FinishAt<d.StartedAt||d.Claimed&&(d.ClaimedAt<d.FinishAt||d.ClaimedAt>Economy.LastTrustedAt)||!Economy.Receipts.Any(x=>x.CommandId==d.Id))throw new ArgumentException("Invalid dispatch timer");var proof=RoundRewardPolicy.VerifyCertified(config,d.Layout.Challenge,d.Layout);if(proof.Stars<1||!d.Rewards.Select(x=>x.ItemId+":"+x.Quantity).SequenceEqual(def.Rewards.Select(x=>x.ItemId+":"+EconomyMath.WithBonus(x.Quantity,d.YieldBp,10000))))throw new ArgumentException("Altered dispatch reward");}
   foreach(string node in Research){var def=config.Operations.Node(node);if(!string.IsNullOrEmpty(def.Prerequisite)&&!Research.Contains(def.Prerequisite))throw new ArgumentException("Missing completed prerequisite");}
   foreach(var p in ResearchQueue){var def=config.Operations.Node(p.NodeId);if(Research.Contains(p.NodeId)||!string.IsNullOrEmpty(def.Prerequisite)&&!Research.Contains(def.Prerequisite)||p.StartedAt<0||p.StartedAt>Economy.LastTrustedAt||p.ReductionBp<0||p.ReductionBp>5000||p.SpeedupSeconds<0||p.FinishAt<p.StartedAt||p.FinishAt-p.StartedAt!=EconomyMath.Duration(def.Seconds,p.ReductionBp)-p.SpeedupSeconds||!Economy.Receipts.Any(x=>x.CommandId==p.Id))throw new ArgumentException("Invalid research timer");}
  }
 }
 public sealed partial class EmpireEngine {
  public CommandReceipt StartDispatch(string id,string template,Board layout,long now){return Command(id,template+"|"+(layout==null?"":layout.Fingerprint()),"dispatch","start",now,(a,t)=>{
   var def=config.Operations.Dispatch(template);if(!a.Businesses.Any(x=>x.Level>0)||Cleared(a)<def.UnlockClears||a.Dispatches.Count(x=>!x.Claimed)>=EmpireBenefits.DispatchSlots(config,a))throw new InvalidOperationException("Dispatch capacity or progression unavailable");if(a.Dispatches.Count(x=>x.StartedAt/86400==now/86400)>=config.Operations.DailyDispatchStarts)throw new InvalidOperationException("Today's dispatch reward budget is reserved. Free puzzles remain available.");
   if(layout==null||!a.Economy.Receipts.Any(x=>x.CommandId=="certified-first-clear:"+layout.Challenge))throw new InvalidOperationException("Demonstrate this layout in a real successful city first");var quote=RoundRewardPolicy.VerifyCertified(config,layout.Challenge,layout);var result=Resolver.Run(layout,Campaign.Get(layout.Challenge).Multiplier);var actual=CityCollections.Contributors(layout,result);if(quote.Stars<1||!layout.Nodes.Any(x=>x.Kind==def.RequiredRecipe&&actual.Contains(x.Id)))throw new InvalidOperationException("This route needs a contributing "+def.RequiredRecipe);
   foreach(var cost in def.Costs)t.Spend(cost.ItemId,cost.Quantity);int reduction=EmpireBenefits.Bonus(config,a,"dispatch-time-bp"),yield=EmpireBenefits.Bonus(config,a,"dispatch-yield-bp");a.Dispatches.Add(new DispatchOperation{Id=id,Template=template,Layout=layout.Copy(),StartedAt=now,FinishAt=checked(now+EconomyMath.Duration(def.Seconds,reduction)),ReductionBp=reduction,YieldBp=yield,Rewards=def.Rewards.Select(x=>new ItemAmount(x.ItemId,EconomyMath.WithBonus(x.Quantity,yield,10000))).ToArray()});Event(a,id,EmpireEventKind.DispatchStarted,template,now,1);
  });}
  public CommandReceipt ClaimDispatch(string dispatchId,long now){return Command("dispatch-claim:"+dispatchId,dispatchId,"dispatch","claim",now,(a,t)=>{
   var d=a.Dispatches.Find(x=>x.Id==dispatchId)??throw new InvalidOperationException("Dispatch unavailable");if(d.Claimed||now<d.FinishAt)throw new InvalidOperationException("Dispatch has not returned");bool first=!a.Dispatches.Any(x=>x.Claimed);foreach(var reward in d.Rewards)t.Grant(reward.ItemId,reward.Quantity);if(first)t.Grant("RECRUIT_TICKET",1);d.Claimed=true;d.ClaimedAt=now;Event(a,"dispatch-claim:"+dispatchId,EmpireEventKind.DispatchClaimed,d.Template,now,1);
  });}
  public CommandReceipt StartResearch(string id,string node,long now){return Command(id,node,"research","start",now,(a,t)=>{
   var def=config.Operations.Node(node);if(Cleared(a)<def.UnlockClears||Cleared(a)<config.Operations.ResearchUnlockClears||a.Dispatches.Count(x=>x.Claimed)<config.Operations.ResearchUnlockClaims)throw new InvalidOperationException("Research unlocks after "+config.Operations.ResearchUnlockClears+" city wins and "+config.Operations.ResearchUnlockClaims+" returned dispatches");if(a.ResearchQueue.Count>0||a.Research.Contains(node)||!string.IsNullOrEmpty(def.Prerequisite)&&!a.Research.Contains(def.Prerequisite))throw new InvalidOperationException("Research queue or prerequisite unavailable");foreach(var cost in def.Costs)t.Spend(cost.ItemId,cost.Quantity);int reduction=EmpireBenefits.Bonus(config,a,"research-time-bp");a.ResearchQueue.Add(new ResearchProject{Id=id,NodeId=node,StartedAt=now,FinishAt=checked(now+EconomyMath.Duration(def.Seconds,reduction)),ReductionBp=reduction});Event(a,id,EmpireEventKind.ResearchStarted,node,now,1);
  });}
  public CommandReceipt FinishResearch(string projectId,long now){return Command("research-finish:"+projectId,projectId,"research","finish",now,(a,t)=>{
   var p=a.ResearchQueue.Find(x=>x.Id==projectId)??throw new InvalidOperationException("Research project unavailable");if(now<p.FinishAt)throw new InvalidOperationException("Research is still running");
   // Settle every old production interval before adding a new bonus: research never increases past output.
   foreach(var b in a.Businesses.Where(x=>x.Level>0)){var project=a.Construction.Find(x=>x.BusinessId==b.Id);if(project!=null&&project.FinishAt<now)throw new InvalidOperationException("Complete the ready builder project before applying new research");var q=ProductionPolicy.Quote(config,b,now,EmpireBenefits.Bonus(config,a,"production-bp"),EmpireBenefits.Bonus(config,a,"storage-bp"));if(q.Amount>0)t.Grant(q.ItemId,q.Amount);b.ProducedAt=now;b.Carry=q.Carry;}
   a.Research.Add(p.NodeId);a.ResearchQueue.Remove(p);Event(a,"research-finish:"+projectId,EmpireEventKind.ResearchCompleted,p.NodeId,now,1);
  });}
  public CommandReceipt SpendSpeedup(string id,string projectId,string sourceItem,int minutes,long now){return Command(id,projectId+"|"+sourceItem+"|"+minutes,"speedup","use",now,(a,t)=>{
   if(minutes<1||minutes>1000000)throw new ArgumentException("Invalid speedup amount");var build=a.Construction.Find(x=>x.Id==projectId);var research=a.ResearchQueue.Find(x=>x.Id==projectId);var dispatch=a.Dispatches.Find(x=>x.Id==projectId&&!x.Claimed);long finish=build?.FinishAt??research?.FinishAt??dispatch?.FinishAt??throw new InvalidOperationException("Timer unavailable");string specialized=build!=null?"CONSTRUCTION_SPEEDUP_MIN":research!=null?"RESEARCH_SPEEDUP_MIN":"DISPATCH_SPEEDUP_MIN";if(sourceItem!=specialized&&sourceItem!="GENERAL_SPEEDUP_MIN")throw new InvalidOperationException("Choose the correct speedup currency");if(finish<=now)throw new InvalidOperationException("Timer is already ready");int applied=(int)Math.Min(finish-now,checked(minutes*60L));t.Spend(sourceItem,minutes);if(build!=null){build.FinishAt-=applied;build.SpeedupSeconds+=applied;}else if(research!=null){research.FinishAt-=applied;research.SpeedupSeconds+=applied;}else{dispatch.FinishAt-=applied;dispatch.SpeedupSeconds+=applied;}Event(a,id,EmpireEventKind.SpeedupSpent,projectId,now,applied);
  });}
 }
}
